-- Additive, rerunnable library core.
CREATE TABLE IF NOT EXISTS library_categories (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL UNIQUE,is_active TINYINT(1) NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS library_authors (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS library_books (
 id INT AUTO_INCREMENT PRIMARY KEY,isbn VARCHAR(40) NULL UNIQUE,title VARCHAR(240) NOT NULL,publisher VARCHAR(160) NULL,publication_year SMALLINT NULL,
 category_id INT NULL,digital_storage_key VARCHAR(255) NULL,digital_original_name VARCHAR(255) NULL,digital_mime VARCHAR(120) NULL,
 created_by INT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
 CONSTRAINT fk_library_book_category FOREIGN KEY(category_id) REFERENCES library_categories(id) ON DELETE SET NULL,
 CONSTRAINT fk_library_book_creator FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS library_book_authors(book_id INT NOT NULL,author_id INT NOT NULL,PRIMARY KEY(book_id,author_id),CONSTRAINT fk_library_ba_book FOREIGN KEY(book_id) REFERENCES library_books(id) ON DELETE CASCADE,CONSTRAINT fk_library_ba_author FOREIGN KEY(author_id) REFERENCES library_authors(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS library_copies(id INT AUTO_INCREMENT PRIMARY KEY,book_id INT NOT NULL,accession_no VARCHAR(80) NOT NULL UNIQUE,status ENUM('Available','Issued','Lost','Maintenance') NOT NULL DEFAULT 'Available',CONSTRAINT fk_library_copy_book FOREIGN KEY(book_id) REFERENCES library_books(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS library_loans(id INT AUTO_INCREMENT PRIMARY KEY,copy_id INT NOT NULL,student_id INT NOT NULL,issued_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,due_at DATETIME NOT NULL,returned_at DATETIME NULL,fine_paise BIGINT UNSIGNED NOT NULL DEFAULT 0,status ENUM('Issued','Returned','Lost') NOT NULL DEFAULT 'Issued',issued_by INT NOT NULL,returned_by INT NULL,CONSTRAINT fk_library_loan_copy FOREIGN KEY(copy_id) REFERENCES library_copies(id) ON DELETE RESTRICT,CONSTRAINT fk_library_loan_student FOREIGN KEY(student_id) REFERENCES users(id) ON DELETE RESTRICT,CONSTRAINT fk_library_loan_issuer FOREIGN KEY(issued_by) REFERENCES users(id) ON DELETE RESTRICT,CONSTRAINT fk_library_loan_returner FOREIGN KEY(returned_by) REFERENCES users(id) ON DELETE SET NULL,KEY idx_library_loan_student(student_id,status),CONSTRAINT chk_library_loan_dates CHECK(due_at>=issued_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS library_reservations(id INT AUTO_INCREMENT PRIMARY KEY,book_id INT NOT NULL,student_id INT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,status ENUM('Waiting','Fulfilled','Cancelled') NOT NULL DEFAULT 'Waiting',UNIQUE KEY uq_library_reservation(book_id,student_id,status),CONSTRAINT fk_library_reservation_book FOREIGN KEY(book_id) REFERENCES library_books(id) ON DELETE CASCADE,CONSTRAINT fk_library_reservation_student FOREIGN KEY(student_id) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;